import { test } from 'node:test';
import assert from 'node:assert/strict';
import { makeRepo, cleanup } from '../../../engine-tests/helpers.mjs';
import { buildContext } from '../../../engine/checks/helpers/repo-context.mjs';
import rule from '../worldRules/references-integrity.mjs';

const PACK = '.claudinite/local/packs/mypack/';

const run = (files) => {
  const root = makeRepo({ changed: files });
  try { return rule.run(buildContext({ root, mode: 'all' })); } finally { cleanup(root); }
};

test('references-integrity: is inert when no pack carries markers or a references doc', () => {
  assert.deepEqual(run({
    [`${PACK}RULES.md`]: '- **Doing a thing** — do it well, with no recorded rationale.\n',
    'src/app.js': 'x\n',
  }), []);
});

test('references-integrity: a marker resolving to its entry is clean', () => {
  assert.deepEqual(run({
    [`${PACK}RULES.md`]: '- **Doing a thing** — do it the settled way. (3)\n',
    [`${PACK}references.md`]: '- **(RULES-3)** Doing it the other way failed twice (#12).\n',
  }), []);
});

test('references-integrity: a multi-citation marker resolves each number', () => {
  const files = {
    [`${PACK}RULES.md`]: '- **Doing a thing** — do it the settled way. (3, 7)\n',
    [`${PACK}references.md`]: '- **(RULES-3)** First reason.\n- **(RULES-7)** Second reason.\n',
  };
  assert.deepEqual(run(files), []);
  files[`${PACK}references.md`] = '- **(RULES-3)** First reason.\n';
  const findings = run(files);
  assert.equal(findings.length, 1);
  assert.match(findings[0].what, /\(7\)/);
});

test('references-integrity: flags a marker with no references doc beside the pack', () => {
  const findings = run({
    [`${PACK}RULES.md`]: '- **Doing a thing** — do it the settled way. (3)\n',
  });
  assert.equal(findings.length, 1);
  assert.equal(findings[0].severity, 'blocking');
  assert.match(findings[0].what, /no references\.md/);
});

test('references-integrity: flags a marker whose number has no entry', () => {
  const findings = run({
    [`${PACK}RULES.md`]: '- **Doing a thing** — do it the settled way. (4)\n',
    [`${PACK}references.md`]: '- **(RULES-3)** A reason for a different rule.\n',
  });
  assert.equal(findings.length, 1);
  assert.match(findings[0].what, /\(4\)/);
});

test('references-integrity: reads SKILL.md markers too', () => {
  const findings = run({
    [`${PACK}skills/do-a-thing/SKILL.md`]: 'Step one, because it is settled. (9)\n',
    [`${PACK}references.md`]: '- **(do-a-thing-3)** Unrelated.\n',
  });
  assert.equal(findings.length, 1);
  assert.match(findings[0].file, /SKILL\.md$/);
});

test('references-integrity: namespaces are per file — a RULES.md marker never resolves through a skill\'s entry', () => {
  const findings = run({
    [`${PACK}RULES.md`]: '- **Doing a thing** — the settled way. (3)\n',
    [`${PACK}skills/do-a-thing/SKILL.md`]: 'Step one, because it is settled. (3)\n',
    [`${PACK}references.md`]: '- **(do-a-thing-3)** The skill\'s reason.\n',
  });
  assert.equal(findings.length, 1);
  assert.match(findings[0].file, /RULES\.md$/);
  assert.match(findings[0].what, /RULES-3/);
});

test('references-integrity: an inline issue id or an ordinary parenthetical is not a marker', () => {
  assert.deepEqual(run({
    [`${PACK}RULES.md`]: [
      '- **Doing a thing** — do it (#1119).',
      '- **Doing another** — with the flag (see below).',
      '- **Counting** — got it right 5 runs in 5.',
    ].join('\n') + '\n',
  }), []);
});

test('references-integrity: a check entry naming a declared check is clean, an unknown one flags', () => {
  const files = {
    [`${PACK}declared-checks.json`]: '[ { "id": "my-check", "severity": "advisory", "failureMessage": "m" } ]\n',
    [`${PACK}references.md`]: '- **(check:my-check)** The reason the check exists.\n',
  };
  assert.deepEqual(run(files), []);
  files[`${PACK}references.md`] = '- **(check:retired-check)** A reason for a check that is gone.\n';
  const findings = run(files);
  assert.equal(findings.length, 1);
  assert.match(findings[0].what, /retired-check/);
});

test('references-integrity: a check entry naming a coded rule module is clean', () => {
  assert.deepEqual(run({
    [`${PACK}worldRules/my-rule.mjs`]: "const rule = { id: 'my-coded-rule', severity: 'blocking' };\nexport default rule;\n",
    [`${PACK}references.md`]: '- **(check:my-coded-rule)** The reason.\n',
  }), []);
});

test('references-integrity: canon-root packs/ are scanned the same way', () => {
  const findings = run({
    'packs/somepack/RULES.md': '- **Doing a thing** — the settled way. (2)\n',
  });
  assert.equal(findings.length, 1);
  assert.match(findings[0].what, /no references\.md/);
});

import { finding } from '../../../engine/checks/helpers/findings.mjs';

// The integrity half of the writing-pack-prose references convention: a rule in
// a pack's prose ends with a bare `(n)` marker citing an entry in the pack's
// own references.md, and a `check:` entry there names a check the pack still
// carries. Both sides fail silently without this — a dangling marker cites a
// rationale nobody recorded, and an orphaned check entry lets a future
// revalidation reaffirm a check that no longer exists — so the cross-file
// resolution is machine-held here; what the convention *means* stays in the
// writing-pack-prose skill.
//
// Two-root form: the path pattern keys on the `packs/<pack>/` suffix, so it
// matches the canon home's `packs/`, a member's `.claudinite/local/packs/` and
// the legacy `.claudinite/local_packs/` alike (a member's vendored
// `.claudinite/shared/` copy is linguist-vendored and never in the file set).
//
// RELEVANCE FIRST (engine/checks/README.md): the convention is opt-in per rule,
// so a pack with no markers and no check entries produces nothing.
const PROSE = /(^|\/)(?:local_)?packs\/[^/]+\/(?:RULES\.md|skills\/[^/]+\/SKILL\.md)$/;
const PACK_DIR = /(^|.*\/)(?:local_)?packs\/[^/]+\//;

// A citation marker: a line ENDING with `(3)` or `(3, 7)` — an inline issue id
// `(#1119)` or a worded parenthetical never matches, and a trailing period puts
// the marker after it by convention. A marker resolves within its own file's
// namespace: `(3)` in RULES.md cites the `RULES-3` entry, in a skill the
// `<skill-name>-3` entry.
const MARKER = /\((\d+(?:\s*,\s*\d+)*)\)\s*$/;
const ENTRY = /^\s*-\s+\*\*\(([A-Za-z][\w-]*-\d+)\)\*\*/;
const CHECK_ENTRY = /^\s*-\s+\*\*\(check:([\w-]+)\)\*\*/;

// A check id as pack files spell it: declared-checks.json's `"id": "x"` or a
// coded rule module's `id: 'x'`.
const CHECK_IDS = /\bid['"]?\s*:\s*['"]([\w-]+)['"]/g;

const rule = {
  id: 'references-integrity',
  severity: 'blocking',
  since: '2026-09-01',
  description: 'Every (n) rationale marker in pack prose resolves to an entry in that pack\'s references.md, and every check: entry there names a check the pack still carries',
  doc: 'packs/claudinite-growth/skills/writing-pack-prose/SKILL.md',
  why: 'the references doc is what a periodic review reaffirms rules and checks against — a dangling marker cites a rationale nobody recorded, and an orphaned check entry lets a review reaffirm a check that no longer exists',

  run(ctx) {
    const out = [];
    const entriesOf = new Map(); // pack dir -> Set of entry numbers, or null when no references.md

    const entries = (packDir) => {
      if (!entriesOf.has(packDir)) {
        const text = ctx.read(`${packDir}references.md`);
        entriesOf.set(packDir, text === null
          ? null
          : new Set(text.split('\n').map((l) => ENTRY.exec(l)?.[1]).filter(Boolean)));
      }
      return entriesOf.get(packDir);
    };

    for (const file of ctx.files) {
      if (!PROSE.test(file)) continue;
      const text = ctx.read(file);
      if (text === null) continue;
      const packDir = PACK_DIR.exec(file)[0];
      // The file's entry namespace: RULES for RULES.md, the skill's own name
      // for a skills/<name>/SKILL.md.
      const stem = file.endsWith('/RULES.md') || file === 'RULES.md'
        ? 'RULES'
        : file.split('/').at(-2);
      for (const line of text.split('\n')) {
        const m = MARKER.exec(line);
        if (!m) continue;
        const known = entries(packDir);
        for (const n of m[1].split(',').map((s) => s.trim())) {
          const key = `${stem}-${n}`;
          if (known === null) {
            out.push(finding(rule, {
              file,
              what: `cites rationale entry (${n}) but the pack has no references.md`,
              fix: `add ${packDir}references.md with a "- **(${key})** <reason>" entry, or drop the marker — the writing-pack-prose skill owns the convention`,
            }));
          } else if (!known.has(key)) {
            out.push(finding(rule, {
              file,
              what: `cites rationale entry (${n}), which ${packDir}references.md does not carry as ${key}`,
              fix: `add the "- **(${key})** <reason>" entry, or drop the marker; entry numbers are stable identifiers, so a removed entry's number is never reused`,
            }));
          }
        }
      }
    }

    // The reverse direction: check entries against the checks the pack carries.
    for (const file of ctx.files) {
      if (!/(^|\/)(?:local_)?packs\/[^/]+\/references\.md$/.test(file)) continue;
      const text = ctx.read(file);
      if (text === null) continue;
      const packDir = PACK_DIR.exec(file)[0];
      const cited = text.split('\n').map((l) => CHECK_ENTRY.exec(l)?.[1]).filter(Boolean);
      if (!cited.length) continue;
      const ids = new Set();
      for (const f of ctx.files) {
        if (!f.startsWith(packDir) || !/\.(mjs|json)$/.test(f)) continue;
        for (const m of (ctx.read(f) ?? '').matchAll(CHECK_IDS)) ids.add(m[1]);
      }
      for (const id of cited) {
        if (ids.has(id)) continue;
        out.push(finding(rule, {
          file,
          what: `carries a rationale entry for check:${id}, which the pack does not carry`,
          fix: 'remove the entry with the check it explained, or point it at the check\'s current id',
        }));
      }
    }
    return out;
  },
};

export default rule;

